pub(super) fn svg_text_anchor(anchor_x: f32, width: f32) -> &'static str {
    if anchor_x <= 0.0 {
        "start"
    } else if anchor_x >= width {
        "end"
    } else {
        "middle"
    }
}

pub(super) fn escape_svg_text(text: &str) -> String {
    let mut escaped = String::with_capacity(text.len());
    for ch in text.chars() {
        match ch {
            '&' => escaped.push_str("&amp;"),
            '<' => escaped.push_str("&lt;"),
            '>' => escaped.push_str("&gt;"),
            '"' => escaped.push_str("&quot;"),
            '\'' => escaped.push_str("&apos;"),
            _ => escaped.push(ch),
        }
    }
    escaped
}
